// Builds src/signal-discovery/communes-fr.ts from Etalab's official list of French communes (INSEE COG).
//   npm pack @etalab/decoupage-administratif@4.0.0 && tar -xzf etalab-decoupage-administratif-4.0.0.tgz
//   node scripts/build-communes-fr.mjs package/data/communes.json
// Deterministic: same input → same file. Not run at build time; the generated file is committed.
import {readFileSync,writeFileSync} from 'node:fs';

const SOURCE='@etalab/decoupage-administratif@4.0.0';
const MIN_POPULATION=2000;
// A homonym is kept only when its largest bearer is at least this many times as populated as the next one.
const DOMINANCE=5;
// Same folding as src/discovery/geo-fr.ts foldPlace.
const fold=s=>s.normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[’']/g,' ').replace(/[-_]+/g,' ').toLowerCase().replace(/\s+/g,' ').trim();

const input=process.argv[2];
if(!input){console.error('usage: node scripts/build-communes-fr.mjs <communes.json>');process.exit(1)}
// Departments of geo-fr only (metropolitan France and the five overseas departments): no overseas collectivity.
const all=JSON.parse(readFileSync(input,'utf8')).filter(c=>c.type==='commune-actuelle'&&/^(?:\d{2}|2A|2B|97[1-6])$/.test(c.departement??''));
const byName=new Map();
for(const c of all){const k=fold(c.nom);if(!byName.has(k))byName.set(k,[]);byName.get(k).push(c)}
const rows=[];
for(const [name,list] of byName){
 const [top,next]=[...list].sort((a,b)=>(b.population??0)-(a.population??0));
 if((top.population??0)<MIN_POPULATION)continue;
 if(next&&(next.population??0)*DOMINANCE>(top.population??0))continue;
 rows.push(`${name}|${top.departement}`);
}
rows.sort((a,b)=>a<b?-1:a>b?1:0);
writeFileSync(new URL('../src/signal-discovery/communes-fr.ts',import.meta.url),`// GENERATED by scripts/build-communes-fr.mjs — do not edit by hand.
// Source: Etalab, ${SOURCE} (data/communes.json, INSEE COG; MIT / Licence Ouverte).
// Current communes of ${MIN_POPULATION.toLocaleString('en')} inhabitants or more: folded name (geo-fr foldPlace) | department code. A name
// borne by several communes is kept only when one of them is at least ${DOMINANCE} times as populated as the next:
// otherwise it is left out (ambiguous, never guessed).
export const COMMUNES_FR_SOURCE='${SOURCE}';
export const COMMUNES_FR=\`${rows.join('\n')}\`;
`);
console.log(`${rows.length} communes`);
